// Originally AUTO-GENERATED by gen_mainline_initializer_stubs.sh; now hand-written.
// Edit only if a real OH-side service replaces the no-op.
package android.app.job;

import android.content.Context;

import java.lang.reflect.Field;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Mainline APEX initializer.
 *
 * <p>On Android 11 JobScheduler ships in an APEX that OH does not have, and
 * {@code SystemServiceRegistry.<clinit>} calls this class to register the wrapper. While this
 * was a no-op, {@code Context.getSystemService(JOB_SCHEDULER_SERVICE)} returned null, and any
 * caller that assumes the platform contract - that the service is always present - failed at
 * the cast rather than at a null check. Measured on the board: McDonald's 26.31.1 died during
 * Application creation with
 * {@code NullPointerException: null cannot be cast to non-null type android.app.job.JobScheduler},
 * thrown from Split.io's SDK inside androidx.startup, which aborted the whole startup chain.
 *
 * <p>AOSP registers {@code JobSchedulerImpl} over the {@code IJobScheduler} binder. There is no
 * such binder here, and {@code registerStaticService} would resolve it through ServiceManager and
 * throw, so the fetcher is installed directly and backed by {@link LocalJobScheduler}: jobs are
 * accepted and remembered, never run. That is the honest behaviour for a device with no job
 * service - an app can schedule, query and cancel coherently, and simply never sees its jobs
 * execute - and it is what unblocks startup. Replace this with a real OH-backed scheduler when
 * one exists; callers that depend on jobs actually running will need it.
 */
public final class JobSchedulerFrameworkInitializer {
    private JobSchedulerFrameworkInitializer() {}

    public static void registerServiceWrappers() {
        try {
            install();
        } catch (Throwable error) {
            // Never break SystemServiceRegistry.<clinit>: a missing JobScheduler is survivable
            // for apps that null-check, and a thrown initializer is not survivable for anyone.
            System.err.println("[WESTLAKE-JOBSCHEDULER] registration failed: " + error);
        }
    }

    @SuppressWarnings("unchecked")
    private static void install() throws Exception {
        Class<?> registry = Class.forName("android.app.SystemServiceRegistry");
        Class<?> fetcherType = Class.forName("android.app.SystemServiceRegistry$ServiceFetcher");

        final JobScheduler service = new LocalJobScheduler();
        Object fetcher = Proxy.newProxyInstance(
                fetcherType.getClassLoader(), new Class<?>[] {fetcherType},
                new InvocationHandler() {
                    @Override
                    public Object invoke(Object proxy, Method method, Object[] args) {
                        String name = method.getName();
                        if ("getService".equals(name)) {
                            return service;
                        }
                        // Default method on the interface; the scheduler needs no context, and
                        // answering true keeps the registry off the ContextImpl path. Returning
                        // the wrong type here would fail inside the proxy, not at the call site.
                        if ("supportsFetchWithoutContext".equals(name)) {
                            return Boolean.TRUE;
                        }
                        if ("hashCode".equals(name)) {
                            return System.identityHashCode(proxy);
                        }
                        if ("equals".equals(name)) {
                            return proxy == (args == null ? null : args[0]);
                        }
                        if ("toString".equals(name)) {
                            return "[WESTLAKE-JOBSCHEDULER fetcher]";
                        }
                        Class<?> returnType = method.getReturnType();
                        if (returnType == boolean.class) {
                            return Boolean.FALSE;
                        }
                        if (returnType.isPrimitive() && returnType != void.class) {
                            return 0;
                        }
                        return null;
                    }
                });

        Field fetchers = registry.getDeclaredField("SYSTEM_SERVICE_FETCHERS");
        fetchers.setAccessible(true);
        ((Map<String, Object>) fetchers.get(null)).put(Context.JOB_SCHEDULER_SERVICE, fetcher);

        Field names = registry.getDeclaredField("SYSTEM_SERVICE_NAMES");
        names.setAccessible(true);
        ((Map<Class<?>, String>) names.get(null))
                .put(JobScheduler.class, Context.JOB_SCHEDULER_SERVICE);

        System.err.println("[WESTLAKE-JOBSCHEDULER] registered local scheduler for "
                + Context.JOB_SCHEDULER_SERVICE);
    }

    /** Accepts and remembers jobs; never runs them. */
    private static final class LocalJobScheduler extends JobScheduler {
        private final Object lock = new Object();
        private final List<JobInfo> pending = new ArrayList<>();

        @Override
        public int schedule(JobInfo job) {
            if (job == null) {
                return JobScheduler.RESULT_FAILURE;
            }
            synchronized (lock) {
                remove(job.getId());
                pending.add(job);
            }
            return JobScheduler.RESULT_SUCCESS;
        }

        @Override
        public int enqueue(JobInfo job, JobWorkItem work) {
            return schedule(job);
        }

        @Override
        public int scheduleAsPackage(JobInfo job, String packageName, int userId, String tag) {
            return schedule(job);
        }

        @Override
        public void cancel(int jobId) {
            synchronized (lock) {
                remove(jobId);
            }
        }

        @Override
        public void cancelAll() {
            synchronized (lock) {
                pending.clear();
            }
        }

        @Override
        public List<JobInfo> getAllPendingJobs() {
            synchronized (lock) {
                return new ArrayList<>(pending);
            }
        }

        @Override
        public JobInfo getPendingJob(int jobId) {
            synchronized (lock) {
                for (JobInfo job : pending) {
                    if (job.getId() == jobId) {
                        return job;
                    }
                }
            }
            return null;
        }

        @Override
        public List<JobInfo> getStartedJobs() {
            // Nothing ever starts.
            return Collections.emptyList();
        }

        @Override
        public List<JobSnapshot> getAllJobSnapshots() {
            return Collections.emptyList();
        }

        private void remove(int jobId) {
            for (int i = pending.size() - 1; i >= 0; i--) {
                if (pending.get(i).getId() == jobId) {
                    pending.remove(i);
                }
            }
        }
    }
}
